<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice='';$error='';
function dn_my_clan(mysqli $db,int $uid): ?array {$stmt=$db->prepare('SELECT c.*,cm.member_rank FROM clan_members cm JOIN clans c ON c.id=cm.clan_id WHERE cm.user_id=? LIMIT 1');if(!$stmt)return null;$stmt->bind_param('i',$uid);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$stmt->close();return$r?:null;}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{pv_require_csrf();$action=(string)($_POST['action']??'');$mine=dn_my_clan($db,$uid);if($action==='create'){if($mine)throw new RuntimeException('Leave your current clan before creating another.');$name=trim((string)($_POST['name']??''));$tag=strtoupper(trim((string)($_POST['tag']??'')));$desc=trim((string)($_POST['description']??''));if(!preg_match('/^[A-Za-z0-9 _-]{3,80}$/',$name))throw new RuntimeException('Clan name must be 3–80 characters.');if(!preg_match('/^[A-Z0-9]{2,8}$/',$tag))throw new RuntimeException('Clan tag must be 2–8 letters/numbers.');$now=time();$db->begin_transaction();$stmt=$db->prepare('INSERT INTO clans(name,tag,description,owner_id,created_at) VALUES(?,?,?,?,?)');$stmt->bind_param('sssii',$name,$tag,$desc,$uid,$now);if(!$stmt->execute())throw new RuntimeException($stmt->errno===1062?'That clan name or tag is already used.':$stmt->error);$cid=(int)$db->insert_id;$stmt->close();$rank='leader';$stmt=$db->prepare('INSERT INTO clan_members(clan_id,user_id,member_rank,joined_at) VALUES(?,?,?,?)');$stmt->bind_param('iisi',$cid,$uid,$rank,$now);$stmt->execute();$stmt->close();$db->commit();$notice='Clan created.';dn_world_event('game','clan.create','Created clan '.$name);}elseif($action==='join'){if($mine)throw new RuntimeException('You already belong to a clan.');$cid=(int)($_POST['clan_id']??0);$stmt=$db->prepare('SELECT id,name FROM clans WHERE id=? LIMIT 1');$stmt->bind_param('i',$cid);$stmt->execute();$c=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$c)throw new RuntimeException('Clan not found.');$rank='member';$now=time();$stmt=$db->prepare('INSERT INTO clan_members(clan_id,user_id,member_rank,joined_at) VALUES(?,?,?,?)');$stmt->bind_param('iisi',$cid,$uid,$rank,$now);if(!$stmt->execute())throw new RuntimeException($stmt->error);$stmt->close();$notice='Joined '.$c['name'].'.';dn_world_event('game','clan.join','Joined clan '.$c['name']);}elseif($action==='leave'){if(!$mine)throw new RuntimeException('You are not in a clan.');if($mine['member_rank']==='leader')throw new RuntimeException('Clan leaders cannot leave while they own the clan.');$stmt=$db->prepare('DELETE FROM clan_members WHERE user_id=?');$stmt->bind_param('i',$uid);$stmt->execute();$stmt->close();$notice='Left clan.';dn_world_event('game','clan.leave','Left a clan');}elseif($action==='disband'){if(!$mine||$mine['member_rank']!=='leader')throw new RuntimeException('Only the clan leader can disband the clan.');$cid=(int)$mine['id'];$stmt=$db->prepare('DELETE FROM clans WHERE id=? AND owner_id=?');$stmt->bind_param('ii',$cid,$uid);$stmt->execute();$stmt->close();$notice='Clan disbanded.';dn_world_event('game','clan.disband','Disbanded own clan');}}catch(Throwable $e){try{$db->rollback();}catch(Throwable){};$error=$e->getMessage();}}
$mine=dn_my_clan($db,$uid);$clans=[];$r=$db->query('SELECT c.*,m.username owner_name,COUNT(cm.user_id) member_count FROM clans c JOIN members m ON m.id=c.owner_id LEFT JOIN clan_members cm ON cm.clan_id=c.id GROUP BY c.id ORDER BY member_count DESC,c.name LIMIT 60');if($r)while($x=$r->fetch_assoc())$clans[]=$x;$roster=[];if($mine){$stmt=$db->prepare('SELECT cm.*,m.username,COALESCE(o.tamer,m.created_avatar,1) tamer FROM clan_members cm JOIN members m ON m.id=cm.user_id LEFT JOIN members_options o ON o.id=m.id WHERE cm.clan_id=? ORDER BY FIELD(cm.member_rank,"leader","officer","member"),m.username');$cid=(int)$mine['id'];$stmt->bind_param('i',$cid);$stmt->execute();$rr=$stmt->get_result();while($x=$rr->fetch_assoc())$roster[]=$x;$stmt->close();}
pv_page_start('Clans','clans.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('clans.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">TAMER ORGANIZATIONS</span><h1>Clans</h1><p class="pv-subtle">Build your crew. Join a clan or create a new home for your fellow tamers.</p></div></div><?php if($notice):?><div class="pv-flash success"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><?php if($mine):?><section class="pv-card pv-clan-hero" style="padding:22px"><span class="pv-eyebrow">YOUR CLAN // [<?=pv_h((string)$mine['tag'])?>]</span><h2><?=pv_h((string)$mine['name'])?></h2><p><?=pv_h((string)$mine['description'])?></p><div class="pv-clan-roster"><?php foreach($roster as $m):?><div class="pv-trainer-card"><div class="pv-trainer-avatar"><img src="<?=pv_h(nxt_skin_url((int)$m['tamer']))?>" alt=""></div><div><strong><?=pv_h((string)$m['username'])?></strong><small><?=pv_h(strtoupper((string)$m['member_rank']))?></small></div></div><?php endforeach;?></div><form method="post" style="margin-top:14px"><?=pv_csrf_field()?><?php if($mine['member_rank']==='leader'):?><button class="pv-button pv-button-danger" name="action" value="disband" onclick="return confirm('Disband this clan?')">Disband Clan</button><?php else:?><button class="pv-button pv-button-secondary" name="action" value="leave">Leave Clan</button><?php endif;?></form></section><?php else:?><section class="pv-card pv-clan-create" style="padding:20px"><h2>Create a clan</h2><form method="post"><?=pv_csrf_field()?><input type="hidden" name="action" value="create"><div class="pv-grid cols-2"><div class="pv-field"><label>Name</label><input name="name" maxlength="80" required></div><div class="pv-field"><label>Tag</label><input name="tag" maxlength="8" required></div></div><div class="pv-field"><label>Description</label><textarea name="description" maxlength="500" rows="3"></textarea></div><button class="pv-button">Create Clan</button></form></section><?php endif;?><section class="pv-card pv-clan-directory" style="padding:20px;margin-top:14px"><h2>Clan Directory</h2><div class="pv-grid cols-3"><?php foreach($clans as $c):?><article class="pv-clan-directory-card"><small>[<?=pv_h((string)$c['tag'])?>] · <?=number_format((int)$c['member_count'])?> MEMBERS</small><h3><?=pv_h((string)$c['name'])?></h3><p><?=pv_h((string)$c['description'])?></p><small>Leader: <?=pv_h((string)$c['owner_name'])?></small><?php if(!$mine):?><form method="post" style="margin-top:10px"><?=pv_csrf_field()?><input type="hidden" name="clan_id" value="<?=(int)$c['id']?>"><button class="pv-button pv-button-secondary" name="action" value="join">Join Clan</button></form><?php endif;?></article><?php endforeach;?></div><?php if(!$clans):?><div class="pv-empty">No clans have been created yet.</div><?php endif;?></section></section></main></div><?php pv_page_end(); ?>
